// Node 2: Verify Razorpay HMAC-SHA256 Signature Using Raw Request Body & Secret
const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || item.json;
const signature = headers['x-razorpay-signature'];
const secret = $env.RAZORPAY_WEBHOOK_SECRET;

// If triggered via Razorpay Webhook, strictly verify HMAC-SHA256 signature
if (signature || body.event) {
  if (!signature || !secret) {
    throw new Error('Security Error: Missing x-razorpay-signature header or RAZORPAY_WEBHOOK_SECRET.');
  }
  const rawBody = item.binary?.data
    ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
    : JSON.stringify(body);

  const expectedSignature = crypto
    .createHmac('sha256', secret)
    .update(rawBody, 'utf8')
    .digest('hex');

  const sigBuf = Buffer.from(String(signature), 'utf8');
  const expBuf = Buffer.from(expectedSignature, 'utf8');
  if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
    throw new Error('Security Error: Invalid Razorpay HMAC-SHA256 Webhook Signature.');
  }

  const paymentEntity = body.payload?.payment?.entity || {};
  const notes = paymentEntity.notes || {};
  return [{
    json: {
      Source: 'RAZORPAY_WEBHOOK',
      Member_ID: notes.member_id,
      Plan: notes.plan || 'Monthly',
      Duration_Months: Number(notes.duration_months || 1),
      Amount: Math.round(Number(paymentEntity.amount || 0) / 100),
      Payment_Method: 'Razorpay',
      Razorpay_Reference: paymentEntity.id,
      Payment_Status: 'Paid',
      Webhook_Processed: 'TRUE'
    }
  }];
}

// Otherwise handle authenticated Manual Payment Form (Cash / UPI)
return [{
  json: {
    Source: 'MANUAL_FORM',
    Member_ID: body.memberId || body.Member_ID,
    Plan: body.plan || 'Monthly',
    Duration_Months: Number(body.durationMonths || 1),
    Amount: Number(body.amount || 0),
    Payment_Method: body.paymentMethod || 'Cash',
    Razorpay_Reference: body.paymentReference || `MANUAL-${Date.now()}`,
    Payment_Status: 'Paid',
    Webhook_Processed: 'TRUE'
  }
}];

// Node 6: Extend Membership Expiry Date with Month-End Clamping
const member = $input.first().json;
const payment = $('2. Verify HMAC-SHA256 Signature & Normalize').first().json;

const todayIST = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

function addMonthsClamped(dateStr, monthsToAdd) {
  const [year, month, day] = dateStr.split('-').map(Number);
  const totalMonths = (month - 1) + Number(monthsToAdd);
  const targetYear = year + Math.floor(totalMonths / 12);
  const targetMonthIndex = totalMonths % 12;
  const maxDaysInTargetMonth = new Date(Date.UTC(targetYear, targetMonthIndex + 1, 0)).getUTCDate();
  const clampedDay = Math.min(day, maxDaysInTargetMonth);
  return `${targetYear}-${String(targetMonthIndex + 1).padStart(2, '0')}-${String(clampedDay).padStart(2, '0')}`;
}

// If current Expiry_Date is still active (>= todayIST), extend from current Expiry_Date; otherwise extend from todayIST
const baseDate = (member.Expiry_Date && member.Expiry_Date >= todayIST) ? member.Expiry_Date : todayIST;
const newExpiryDate = addMonthsClamped(baseDate, payment.Duration_Months || 1);

return [{
  json: {
    Member_ID: member.Member_ID,
    Name: member.Name,
    Phone: member.Phone,
    Plan: payment.Plan || member.Plan,
    Previous_Expiry_Date: member.Expiry_Date,
    New_Expiry_Date: newExpiryDate,
    Payment_ID: `PAY-${Date.now().toString().slice(-6)}`,
    Amount: payment.Amount,
    Payment_Method: payment.Payment_Method,
    Payment_Status: 'Paid',
    Payment_Date: todayIST,
    Razorpay_Reference: payment.Razorpay_Reference,
    Webhook_Processed: 'TRUE'
  }
}];

